function face_tomb_scan_media($category) {
  $allowed = ['png','jpg','jpeg','webp','gif'];
  $fsPath = rtrim($_SERVER['DOCUMENT_ROOT'], '/') . "/AIFACES/{$category}";
  $publicBase = "https://faceofrobin.com/AIFACES/{$category}/";
  $items = [];
  if (is_dir($fsPath)) {
    foreach (scandir($fsPath) as $f) {
      if ($f === '.' || $f === '..') continue;
      $ext = strtolower(pathinfo($f, PATHINFO_EXTENSION));
      if (!in_array($ext, $allowed, true)) continue;
      $items[] = ['url' => $publicBase . rawurlencode($f), 'filename' => $f];
    }
  }
  shuffle($items);
  return $items;
}
$GLASS_ITEMS = face_tomb_scan_media('GLASS');
$HALLWAY_ITEMS = face_tomb_scan_media('HALLWAY');
$ART_ITEMS = face_tomb_scan_media('ART');
