    function makeCheckerTexture(size=256, squares=8, colors=['#7b745f','#5a5344']) { const cv=document.createElement('canvas'); cv.width=cv.height=size; const ctx=cv.getContext('2d'); const sq=size/squares; for(let y=0;y<squares;y++) for(let x=0;x<squares;x++){ ctx.fillStyle=(x+y)%2===0?colors[0]:colors[1]; ctx.fillRect(x*sq,y*sq,sq,sq);} for(let i=0;i<220;i++){ctx.fillStyle=`rgba(0,0,0,${Math.random()*0.07})`;ctx.beginPath();ctx.arc(Math.random()*size,Math.random()*size,Math.random()*2.2,0,Math.PI*2);ctx.fill();} const tex=new THREE.CanvasTexture(cv); tex.wrapS=tex.wrapT=THREE.RepeatWrapping; tex.anisotropy=8; return tex; }
