    const BUCKET = 16, collisionBuckets = new Map();
    function bucketKey(bx,bz){ return `${bx},${bz}`; }
    function addRectCollision(x,z,w,d){ const rect={minX:x-w/2,maxX:x+w/2,minZ:z-d/2,maxZ:z+d/2}; const b0x=Math.floor(rect.minX/BUCKET), b1x=Math.floor(rect.maxX/BUCKET), b0z=Math.floor(rect.minZ/BUCKET), b1z=Math.floor(rect.maxZ/BUCKET); for(let bx=b0x;bx<=b1x;bx++) for(let bz=b0z;bz<=b1z;bz++){ const k=bucketKey(bx,bz); if(!collisionBuckets.has(k)) collisionBuckets.set(k,[]); collisionBuckets.get(k).push(rect);} }
    function resolveCollisions(nextPos){ if(state.godMode) return; const radius=0.42, bx=Math.floor(nextPos.x/BUCKET), bz=Math.floor(nextPos.z/BUCKET); for(let dx=-1;dx<=1;dx++) for(let dz=-1;dz<=1;dz++){ const rects=collisionBuckets.get(bucketKey(bx+dx,bz+dz)); if(!rects) continue; for(const rect of rects){ const nearX=Math.max(rect.minX,Math.min(nextPos.x,rect.maxX)); const nearZ=Math.max(rect.minZ,Math.min(nextPos.z,rect.maxZ)); const ex=nextPos.x-nearX, ez=nextPos.z-nearZ, distSq=ex*ex+ez*ez; if(distSq<radius*radius){ const dist=Math.sqrt(distSq)||0.0001, push=radius-dist; if(Math.abs(ex)>=Math.abs(ez)) nextPos.x += (ex/dist)*push; else nextPos.z += (ez/dist)*push; }}} }
