    function setupMobileControls(){ updateMobileUI(); if(!isTouchDevice) return; document.querySelectorAll('[data-control]').forEach(btn=>{ const ctrl=btn.dataset.control; bindHoldButton(btn,()=>{state[ctrl]=true;},()=>{state[ctrl]=false;}); }); bindHoldButton(sprintBtn,()=>{state.sprint=true;},()=>{state.sprint=false;}); interactBtn.addEventListener('pointerdown',e=>{e.preventDefault();inspectCurrent();},{passive:false}); }
    function setGodMode(enabled){ state.godMode=enabled; godModeBtn.classList.toggle('active', enabled); infoBox.innerHTML = enabled ? '<strong>GOD MODE: ON</strong><br>No collision. You can pass through walls.' : '<strong>GOD MODE: OFF</strong><br>Collision restored.'; }
    hudToggle.addEventListener('click',e=>{ e.preventDefault(); hud.classList.toggle('minimized'); hudToggle.textContent = hud.classList.contains('minimized') ? '+' : '–'; });
    godModeBtn.addEventListener('click',e=>{ e.preventDefault(); setGodMode(!state.godMode); });
    glassLightboxClose.addEventListener('click',e=>{ e.preventDefault(); e.stopPropagation(); glassLightbox.style.display='none'; });
    glassLightbox.addEventListener('click',()=>{ glassLightbox.style.display='none'; });
    renderer.domElement.addEventListener('click',e=>{ const clickables=[...(state.glassRoom?.clickablePlanes||[]),...(state.hallwayRoom?.clickablePlanes||[])]; if(!clickables.length) return; const ray=new THREE.Raycaster(); const pLock=document.pointerLockElement===renderer.domElement; const ndc = pLock ? new THREE.Vector2(0,0) : new THREE.Vector2((e.clientX/window.innerWidth)*2-1,-(e.clientY/window.innerHeight)*2+1); ray.setFromCamera(ndc,camera); const hits=ray.intersectObjects(clickables,false); if(hits.length){ openGlassLightbox(hits[0].object.userData); } });
    overlay.addEventListener('click',()=>{ if(isTouchDevice){ overlay.style.display='none'; state.canLook=true; } else { const req=renderer.domElement.requestPointerLock(); if(req&&typeof req.catch==='function') req.catch(()=>{}); } });
    document.addEventListener('pointerlockchange',()=>{ const locked=document.pointerLockElement===renderer.domElement; state.canLook=locked; overlay.style.display=locked?'none':'grid'; });
    document.addEventListener('mousemove',e=>{ if(!state.canLook) return; const sens=0.0022; state.yaw -= e.movementX*sens; state.pitch -= e.movementY*sens; state.pitch=Math.max(-Math.PI/2+0.01,Math.min(Math.PI/2-0.01,state.pitch)); updateCameraRotation(); });
    document.addEventListener('keydown',e=>{ switch(e.code){ case 'KeyW': state.back=true; break; case 'KeyS': state.forward=true; break; case 'KeyA': state.left=true; break; case 'KeyD': state.right=true; break; case 'ShiftLeft': case 'ShiftRight': state.sprint=true; break; case 'KeyE': inspectCurrent(); break; } });
    document.addEventListener('keyup',e=>{ switch(e.code){ case 'KeyW': state.back=false; break; case 'KeyS': state.forward=false; break; case 'KeyA': state.left=false; break; case 'KeyD': state.right=false; break; case 'ShiftLeft': case 'ShiftRight': state.sprint=false; break; } });
    window.addEventListener('resize',()=>{ camera.aspect=window.innerWidth/window.innerHeight; camera.updateProjectionMatrix(); renderer.setSize(window.innerWidth,window.innerHeight); });
    setupMobileControls(); buildWorldFromGrid(); buildDomedCeiling(); buildGrandHallAccents(); buildRoundedArchitecture(); buildPillars(); buildRoomMarkers(); buildInteractives(); buildPortalStubs(); buildImpossibleRoom(); addLighting(); setupPlayer(); bakeMinimapGrid(); buildGlassTowerRoom(); buildHallwayGalleryRoom();
    const clock = new THREE.Clock();
    function tick(){ const delta=Math.min(clock.getDelta(),0.033); updateMovement(delta); if(state.needsInteractRefresh){ state.needsInteractRefresh=false; findNearestInteractable(); } findNearestInteractable(); animateInteractables(delta); drawMinimap(); renderer.render(scene,camera); requestAnimationFrame(tick); }
    tick();
  </script>
</body>
</html>
